import os
import sys

def check_file_exists(file_name):
    """Checks if a file exists."""
    if os.path.exists(file_name):
        return True
    else:
        return False

def check_file_size(file_name):
    """Checks the size of a file."""
    try:
        with open(file_name, 'r') as f:
            size = f.read().split()
            return int(size[0])
    except Exception as e:
        print(f"Error reading file size: {e}")
        return -1

def check_file_type(file_name):
    """Checks the file type."""
    try:
        with open(file_name, 'r') as f:
            content = f.read()
        return content.lower()
    except Exception as e:
        print(f"Error reading file type: {e}")
        return -1

def print_file_contents(file_name):
    """Prints the contents of a file."""
    try:
        with open(file_name, 'r') as f:
            contents = f.read()
        print(contents)
    except Exception as e:
        print(f"Error reading file contents: {e}")

def copy_file(source, destination):
    """Copies a file from source to destination."""
    try:
        import shutil
        shutil.copy2(source, destination)
        print(f"File copied from {source} to {destination}")
    except Exception as e:
        print(f"Error copying file: {e}")

def move_file(source, destination):
    """Moves a file from source to destination."""
    try:
        import shutil
        shutil.move(source, destination)
        print(f"File moved from {source} to {destination}")
    except Exception as e:
        print(f"Error moving file: {e}")

def find_files(directory, pattern):
    """Finds files in a directory matching a pattern."""
    try:
        import os
        files = os.listdir(directory)
        found_files = []
        for file in files:
            if file.endswith(pattern):
                found_files.append(file)
        return found_files
    except Exception as e:
        print(f"Error finding files: {e}")
        return []

def rename_file(source, destination):
    """Renames a file."""
    try:
        import os
        os.rename(source, destination)
        print(f"File renamed from {source} to {destination}")
    except Exception as e:
        print(f"Error renaming file: {e}")

def delete_file(file_name):
    """Deletes a file."""
    try:
        os.remove(file_name)
        print(f"File deleted: {file_name}")
    except Exception as e:
        print(f"Error deleting file: {e}")

def main():
    """Main function to demonstrate the functions."""
    print("Welcome to the File Management Tool!")
    print("This tool provides basic file operations.")

    # Check if the file exists
    if check_file_exists("my_file.txt"):
        print("File 'my_file.txt' exists.")
    else:
        print("File 'my_file.txt' does not exist.")

    # Check the file size
    if check_file_size("my_file.txt"):
        print("File 'my_file.txt' has a size of 1024 bytes.")
    else:
        print("File 'my_file.txt' does not exist or has an invalid size.")

    # Check the file type
    if check_file_type("my_file.txt"):
        print("File 'my_file.txt' is a text file.")
    else:
        print("File 'my_file.txt' is not a text file.")

    # Print the file contents
    if check_file_exists("my_file.txt"):
        print("Contents of 'my_file.txt':")
        print(check_file_contents("my_file.txt"))
    else:
        print("File 'my_file.txt' does not exist.")

    # Copy the file
    if check_file_exists("my_file.txt"):
        copy_file("my_file.txt", "my_copy_file.txt")
    else:
        print("File 'my_file.txt' does not exist.")

    # Move the file
    if check_file_exists("my_file.txt"):
        move_file("my_file.txt", "my_moved_file.txt")
    else:
        print("File 'my_file.txt' does not exist.")

    # Delete the file
    if check_file_exists("my_file.txt"):
        delete_file("my_file.txt")
    else:
        print("File 'my_file.txt' does not exist.")

    print("File management tool completed.")

if __name__ == "__main__":
    main()
