import os
import shutil

def archive_quarter1_reports():
    """Archives all text files in the 'Quarter1_Reports' directory to a new directory."""

    archive_dir = "Archived_Quarter1"

    # Create the archive directory if it doesn't exist
    if not os.path.exists(archive_dir):
        os.makedirs(archive_dir)

    for filename in os.listdir(os.path.join(os.path.dirname(__file__), "Quarter1_Reports")):
        if filename.endswith(".txt"):
            filepath = os.path.join(os.path.dirname(__file__), "Quarter1_Reports", filename)
            try:
                shutil.copy2(filepath, archive_dir)  # copy2 preserves metadata
                print(f"Archived: {filename}")
            except Exception as e:
                print(f"Error archiving {filename}: {e}")

if __name__ == "__main__":
    archive_quarter1_reports()
