import os

def create_directory(path):
    """Creates a directory at the specified path."""
    try:
        os.makedirs(path, exist_ok=True)  # exist_ok=True prevents error if the directory already exists
        print(f"Directory '{path}' created successfully.")
    except OSError as e:
        print(f"Error creating directory '{path}': {e}")

def list_files(path):
    """Lists the files in the specified directory."""
    try:
        files = os.listdir(path)
        print(f"Files in '{path}': {files}")
    except FileNotFoundError:
        print(f"Directory '{path}' not found.")
    except OSError as e:
        print(f"Error listing files in '{path}': {e}")

def remove_file(path, filename):
    """Removes a file from the specified directory."""
    try:
        os.remove(path + "/" + filename)
        print(f"File '{filename}' removed from '{path}'")
    except FileNotFoundError:
        print(f"File '{filename}' not found in '{path}'")
    except OSError as e:
        print(f"Error removing file '{filename}': {e}")

def copy_file(source, destination):
    """Copies a file from the source to the destination."""
    try:
        shutil.copy2(source, destination)  # copy2 preserves metadata
        print(f"File '{source}' copied to '{destination}'")
    except FileNotFoundError:
        print(f"Source file '{source}' not found.")
    except OSError as e:
        print(f"Error copying file: {e}")

def rename_file(source, destination):
    """Renames a file from the source to the destination."""
    try:
        os.rename(source, destination)
        print(f"File '{source}' renamed to '{destination}'")
    except FileNotFoundError:
        print(f"Source file '{source}' not found.")
    except OSError as e:
        print(f"Error renaming file: {e}")

def find_files(path):
    """Finds all files in the specified directory."""
    try:
        files = os.listdir(path)
        print(f"Files in '{path}': {files}")
    except FileNotFoundError:
        print(f"Directory '{path}' not found.")
    except OSError as e:
        print(f"Error finding files in '{path}': {e}")

def delete_directory(path):
    """Deletes a directory and its contents."""
    try:
        shutil.rmtree(path)
        print(f"Directory '{path}' and its contents deleted.")
    except FileNotFoundError:
        print(f"Directory '{path}' not found.")
    except OSError as e:
        print(f"Error deleting directory: {e}")

# Example usage:
create_directory("WebDevProjects")
list_files("WebDevProjects")
remove_file("WebDevProjects/my_file.txt", "my_file.txt")
copy_file("WebDevProjects/my_file.txt", "backup/my_file.txt")
rename_file("WebDevProjects/my_file.txt", "backup/my_file.txt")
find_files("WebDevProjects")
delete_directory("WebDevProjects")
```

