import os

def count_characters(filename):
    """Counts the number of characters in a file."""
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            content = f.read()
            return len(content)
    except FileNotFoundError:
        return 0  # Handle the case where the file doesn't exist
    except Exception as e:
        print(f"Error reading file: {e}")
        return 0

def wc(filename):
    """Counts the number of lines, words, and characters in a file."""
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            num_lines = len(lines)
            num_words = 0
            num_chars = 0
            for line in lines:
                words = line.split()
                num_words += len(words)
                num_chars += len(line)
            return num_lines, num_words, num_chars
    except FileNotFoundError:
        return 0, 0, 0
    except Exception as e:
        print(f"An error occurred: {e}")
        return 0, 0, 0

def tail(filename):
    """Displays the last part of a file."""
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            if lines:
                return "\n".join(lines[-9:])  # Display the last 10 lines
            else:
                return ""
    except FileNotFoundError:
        return ""
    except Exception as e:
        print(f"An error occurred: {e}")
        return ""

def cat(filename):
    """Displays the contents of a file."""
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            content = f.read()
        return content
    except FileNotFoundError:
        return ""
    except Exception as e:
        print(f"An error occurred: {e}")
        return ""

# Example usage:
filename = "my_text_file.txt"  # Replace with the actual filename
lines, words, chars = count_characters(filename)
print(f"The file '{filename}' contains {lines} lines, {words} words, and {chars} characters.")

last_lines = tail(filename)
print(f"The last part of '{filename}' is: {last_lines}")

content = cat(filename)
print(f"The content of '{filename}' is: {content}")
